function NirvanaPaintEffect({effect,particles}){
  if(!effect)return null;
  return a.jsxs("div",{className:"nirvana-paint-effects","data-paint-effect":effect,"aria-hidden":true,children:[
    a.jsx("style",{children:"\n.nirvana-paint-effects{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:5}\n.nirvana-paint-particle{position:absolute;top:-30px;display:block;pointer-events:none;animation:nirvana-paint-drift var(--duration) linear var(--delay) infinite;will-change:transform}\n.nirvana-paint-particle.snow{color:white;text-shadow:0 0 2px #637ca3;font-family:Georgia,serif}\n.nirvana-paint-particle.stars{color:#e4bd65;text-shadow:0 0 5px #fff2ce;font-family:Georgia,serif;animation-name:nirvana-paint-sparkle}\n.nirvana-paint-particle.petals{border-radius:90% 10% 90% 10%;background:#e8b8ca;box-shadow:inset 2px 1px 3px #ffffff70;opacity:.65}\n.nirvana-paint-particle.bubbles{border:1px solid #97c5e7;border-radius:50%;background:radial-gradient(circle at 30% 28%,#ffffffb3 0 12%,#d8efff25 35%,#b4dcf333 75%);animation-name:nirvana-paint-rise}\n@keyframes nirvana-paint-drift{0%{transform:translate(0,-20px) rotate(0);opacity:0}8%{opacity:.7}90%{opacity:.65}100%{transform:translate(var(--sway),105vh) rotate(240deg);opacity:0}}\n@keyframes nirvana-paint-sparkle{0%{opacity:0;transform:translate(0,-20px) scale(.6) rotate(0)}12%{opacity:.7}40%{opacity:.3}68%{opacity:.8}90%{opacity:.5}100%{opacity:0;transform:translate(var(--sway),105vh) scale(1) rotate(120deg)}}\n@keyframes nirvana-paint-rise{0%{transform:translate(0,105vh);opacity:0}10%{opacity:.55}90%{opacity:.4}100%{transform:translate(var(--sway),0);opacity:0}}\n@media(prefers-reduced-motion:reduce){.nirvana-paint-particle{animation:none!important;transform:none!important;opacity:.25;will-change:auto}}\n"}),
    ...particles.slice(0,effect==="bubbles"?22:32).map((particle,index)=>{
      const size=effect==="stars"?10+index%9:effect==="petals"?6+index%6:effect==="bubbles"?8+index%13:particle.size;
      return a.jsx("span",{className:"nirvana-paint-particle "+effect,style:{left:particle.left+"%",width:effect==="petals"||effect==="bubbles"?size:undefined,height:effect==="petals"?size*.65:effect==="bubbles"?size:undefined,fontSize:size,"--duration":particle.dur+"s","--delay":(-index*1.3)+"s","--sway":((index%2?1:-1)*(15+index%45))+"px",backgroundColor:effect==="petals"?["#e8b8ca","#d3c5ec","#f1d2b0"][index%3]:undefined},children:effect==="snow"?"❄":effect==="stars"?"✧":null},index)
    })
  ]})
}

function NirvanaSecretBox({id="paint-cat",image="/__local/intro/cat-box.gif",message="estoy enamorado de ti!!",placement={}}){
  const[open,setOpen]=x.useState(false);
  x.useEffect(()=>{if(!open)return;const close=event=>{if(event.key==="Escape")setOpen(false)};document.addEventListener("keydown",close);return()=>document.removeEventListener("keydown",close)},[open]);
  return a.jsxs("aside",{className:"nirvana-secret-box",onPointerDown:event=>event.stopPropagation(),style:{position:"absolute",left:14,bottom:38,zIndex:1300,fontFamily:"Tahoma, Geneva, sans-serif",...placement},children:[
    a.jsx("style",{children:`
      .nirvana-secret-trigger{display:grid;place-items:center;width:36px;height:36px;padding:0;border:0;background:transparent;cursor:pointer;border-radius:5px;transition:transform .18s ease;filter:drop-shadow(0 2px 1px rgba(40,52,75,.18))}
      .nirvana-secret-trigger:hover{transform:translateY(-3px) rotate(-4deg)}
      .nirvana-secret-trigger:focus-visible{outline:2px dashed #3d5586;outline-offset:3px}
      .nirvana-secret-note{position:absolute;left:44px;bottom:0;box-sizing:border-box;width:190px;max-width:calc(100vw - 170px);padding:10px 20px 11px 11px;border:1px solid #8aa3cf;border-radius:5px;background:#fffdf5;color:#253552;box-shadow:0 3px 10px rgba(32,51,85,.13);animation:nirvana-note-unfold .25s ease-out;transform-origin:bottom left;user-select:text}
      .nirvana-secret-note:before{content:"";position:absolute;left:-6px;bottom:14px;width:10px;height:10px;background:#fffdf5;border-left:1px solid #8aa3cf;border-bottom:1px solid #8aa3cf;transform:rotate(45deg)}
      .nirvana-secret-close{position:absolute;top:2px;right:3px;border:0;background:transparent;color:#607393;padding:2px 4px;font:13px Tahoma,sans-serif;cursor:pointer;border-radius:3px}
      .nirvana-secret-close:hover{background:#e8f0fd}.nirvana-secret-close:focus-visible{outline:2px solid #3d5586}
      @keyframes nirvana-note-unfold{from{opacity:0;transform:translate(-5px,5px) scale(.93)}to{opacity:1;transform:none}}
      @media(prefers-reduced-motion:reduce){.nirvana-secret-note{animation:none}.nirvana-secret-trigger{transition:none}}
    `}),
    a.jsx("button",{type:"button",className:"nirvana-secret-trigger","aria-label":"Abrir la cajita del gatito","aria-expanded":open,"aria-controls":id+"-note",title:"¿Qué habrá aquí?",onClick:()=>setOpen(value=>!value),children:a.jsx("img",{src:image,alt:"",draggable:false,width:27,height:25,style:{display:"block",width:27,height:"auto",imageRendering:"pixelated"}})}),
    open&&a.jsxs("section",{id:id+"-note",className:"nirvana-secret-note",role:"dialog","aria-label":"Mini mensaje encontrado",children:[
      a.jsx("button",{type:"button",className:"nirvana-secret-close","aria-label":"Cerrar mini mensaje",onClick:()=>setOpen(false),children:"×"}),
      a.jsx("p",{style:{fontSize:9.5,lineHeight:1.4,color:"#697690",margin:"0 0 5px"},children:"Encontraste un mensaje escondido:"}),
      a.jsx("p",{"aria-live":"polite",style:{fontSize:11.5,lineHeight:1.4,margin:0},children:message})
    ]})
  ]})
}
function NirvanaPageSecret({path}){
  const surprises={"/gifts":{id:"gifts-cat",message:"feliz cumpleaños, mi amor!!",placement:{position:"fixed",left:58,bottom:70}},"/quotes":{id:"quotes-cat",message:"me gustas muchísimo",placement:{position:"fixed",left:58,bottom:24}},"/end":{id:"end-cat",message:"eres el amor de mi vida",placement:{position:"fixed",left:58,bottom:24}}};
  surprises["/puzzle"]={id:"puzzle-cat",message:"contigo, todas las piezas encuentran su lugar",placement:{position:"fixed",left:58,bottom:24}};
  surprises["/stickers"]={id:"stickers-cat",message:"te elegiría en todas mis vidas",placement:{position:"fixed",left:58,bottom:24}};
  surprises["/crossword"]={id:"crossword-cat",message:"mi palabra favorita siempre será tu nombre",placement:{position:"fixed",left:58,bottom:24}};
  surprises["/food"]={id:"food-cat",message:"me haces tan feliz, amor de mi vida",placement:{position:"fixed",left:58,bottom:24}};
  return surprises[path]?a.jsx(NirvanaSecretBox,surprises[path],path):null;
}
const nirvanaHomeAnchors={"hi-friend":"dear-nirvana","videos":"art-for-her","books":"movies-that-made-me-think-of-us","principles":"cosas-que-me-hacen-pensar-en-ti","books-to-read":"texts-of-her","quotes":"thoughts-on-you","multiple-lives":"if-we-lived-in-another-era","inspiration-lineage":"ikigai","disney-history":"eres","childhood-obsessions":"when-im","artists":"artists-who-talk-her","musicians":"songs-for-her","fav-places":"places-that-makes-me-think-about-you","tapestry":"her","life-motto":"her-philosophy","website-philosophy":"remember","design-signs":"love-of-my-life","words-concepts":"words-concepts-about-you","with-love":"with-love"};
function nirvanaIsHome(){return /^\/(?:inicio|home)(?:\/|$)/.test(window.location.pathname)}
function nirvanaHomeAnchor(id){return nirvanaIsHome()?(nirvanaHomeAnchors[id]||id):id}
function nirvanaHomeInternalId(id){return nirvanaIsHome()?(Object.keys(nirvanaHomeAnchors).find(key=>nirvanaHomeAnchors[key]===id)||id):id}
function nirvanaHomeElement(id){return document.getElementById(nirvanaHomeAnchor(id))}
const nirvanaHome={"title":"Dear Nirvana","whenTitle":"When I'm...","whenThoughts":["Pienso en ti cuando estoy por dormirme y te conviertes en el último pensamiento que tengo","Pienso en ti cuando abro los ojos por la mañana y recuerdo tu simple existencia :D","Pienso en ti cuando está todo en silencio y disfruto del pequeño detalle de los sonidos","Pienso en ti cuando voy caminando por la calle y me quedo apreciando los gatitos, las flores, la forma de las nubes, etc.","Pienso en ti cuando las canciones de amor me hacen recordarnos","Pienso en ti cuando veo algo que sé que te gustará ver y termino tomándole una foto para ti","Pienso en ti cuando sucede algo que me emociona y tengo la necesidad de contártelo","Pienso en ti cuando tengo un día pesado y necesito despejarme de todo estando contigo"],"ikigaiTitle":"Ikigai (生き甲斐)","ikigaiParagraphs":["Un concepto japonés que se traduce como “una razón de ser”: esa tranquila y dorada sensación de propósito que hace que valga la pena levantarse cada mañana.","Tradicionalmente, habita en la intersección de cuatro caminos: lo que amas, en lo que eres bueno, lo que el mundo necesita y lo que le da sustento a tu vida. Sus cruces reciben los nombres de pasión, misión, vocación y profesión; cada uno es una pieza fundamental, pero ninguno está completo por sí solo.","Sin embargo, más allá de los mapas y diagramas tradicionales, he descubierto una verdad mucho más simple: amarte entrelaza sin esfuerzo cada rincón de mi mundo, alineando en un solo lugar la pasión, la paz, la dirección y una alegría infinita."],"ikigaiClosing":"En un mundo que vive buscando un sentido, ","ikigaiHighlight":"amarte se convirtió en mi Ikigai.","ikigaiPhoto":null,"hiddenSections":["projects","stack","brands","movies","shows","podcasts","history","mom","interests","sf-places","coffee","minds","friends","transferable-skills","furniture","presence","no-bad-design","compliments","favorite-classes","fun-websites","movies-to-watch"],"rememberTitle":"Remember","rememberUrl":"https://x.com/holyaches/status/1731380277404975330?s=20","loveOfMyLifeTitle":"Love of my life","loveOfMyLifeText":"today the love of my life turns 23!!!","stickers":[{"id":"birthday-blue","name":"bdayvana 1","alt":"Sticker My birthday con fondo celeste"},{"id":"stars-blue","name":"star-vana","alt":"Sticker de Nirvana rodeada de estrellas celestes"},{"id":"lomi-blue","name":"lomlvana","alt":"Sticker lomi!!! con fondo celeste"},{"id":"fries","name":"friesvana","alt":"Sticker de Nirvana en una cajita de papas fritas"},{"id":"birthday-yellow","name":"bdayvana 2","alt":"Sticker My birthday con fondo amarillo"},{"id":"stars-yellow","name":"star-vana 2","alt":"Sticker de Nirvana rubia rodeada de estrellas"},{"id":"lomi-yellow","name":"lomlvana 2","alt":"Sticker lomi!!! con fondo amarillo"},{"id":"shark","name":"tiburoncin vana","alt":"Sticker de Nirvana con un disfraz de tiburón"},{"id":"shell","name":"chocovana","alt":"Sticker de Nirvana en una concha"},{"id":"ghost","name":"fantasvana","alt":"Sticker de Nirvana como un fantasmita"},{"id":"chicken","name":"chicken vana","alt":"Sticker de Nirvana con un disfraz de pollito"},{"id":"apple-green","name":"applevana","alt":"Sticker de Nirvana dentro de una manzana roja"},{"id":"apple-red","name":"applevana 2","alt":"Sticker de Nirvana dentro de una manzana roja"},{"id":"lamb","name":"dumplingvana","alt":"Sticker de Nirvana con un disfraz de corderito"},{"id":"thumbs-up","name":"fishvana","alt":"Sticker de Nirvana dando el pulgar arriba"},{"id":"toast","name":"breadvana","alt":"Sticker de Nirvana como una tostada"},{"id":"suit","name":"bossvana","alt":"Sticker de Nirvana con traje negro"},{"id":"apple-costume","name":"applegreenvana","alt":"Sticker de Nirvana con un disfraz de manzana verde"},{"id":"i-love-you","name":"iloveu","alt":"Sticker que dice I love you"},{"id":"jules-wife","name":"juleswife","alt":"Sticker que dice Jules wife"},{"id":"birthday-speech","name":"nirvieday","alt":"Sticker que dice Nirvie Day"},{"id":"i-have-23","name":"ihave23","alt":"Sticker que dice I have 23"}],"gifts":[{"id":"gift-01","name":"Miffy de peluche","photo":"/__local/gifts/gift-01.jpg","color":"#f2a8c8","ribbon":"#fff4f8"},{"id":"gift-02","name":"Pulsera Pandora","photo":"/__local/gifts/gift-02.jpg","color":"#9edcf2","ribbon":"#fff8db"},{"id":"gift-03","name":"Miss Dior","photo":"/__local/gifts/gift-03.jpg","color":"#f5d66f","ribbon":"#fff6d2"},{"id":"gift-04","name":"Cervatillo de peluche","photo":"/__local/gifts/gift-04.jpg","color":"#b9a5e8","ribbon":"#fff4f8"},{"id":"gift-05","name":"Lady Dior","photo":"/__local/gifts/gift-05.avif","color":"#a8d8bd","ribbon":"#fff6dc"},{"id":"gift-06","name":"Murciélaguito","photo":"/__local/gifts/gift-10.jpg","color":"#f3b18f","ribbon":"#fff4f8"},{"id":"gift-07","name":"Chocolates","photo":"/__local/gifts/gift-07.jpg","color":"#ed91b8","ribbon":"#fff7db"},{"id":"gift-08","name":"Flores para ti","photo":"/__local/gifts/gift-08.jpg","color":"#91cfe0","ribbon":"#fff4f8"},{"id":"gift-09","name":"Manta de cervatillo","photo":"/__local/gifts/gift-09.jpg","color":"#c7b8ec","ribbon":"#fff6dc"},{"id":"gift-10","name":"Un gatito","photo":"/__local/gifts/gift-06.jpg","color":"#f2cc75","ribbon":"#fff4f8"}],"paragraphs":["Hoy es 28 de octubre del año 2026, es el segundo cumpleaños que paso junto a ti y mi cabeza dio vueltas y vueltas pensando en qué podía darte que realmente fuera especial y te gustara. Pasé por muchas ideas (y dudas), pero finalmente llegué a esto.","¿Qué es esto?, te preguntarás. Pues es un espacio libre, un espacio lleno de recuerdos, amor, memorias, un espacio creado de mí para ti como una muestra de todo el amor, cariño y alegría que he vivido contigo.","Llevo más de un año amándote y últimamente me siento como si fuera la primera vez que te confieso mi amor. No importa el tiempo que pase porque realmente yo no puedo dejar de pensar en ti."],"quote":"Prometo amarte ferozmente en todas tus formas, ahora y para siempre. Prometo no olvidar nunca que este es un amor de una vez en la vida. Y saber siempre en lo más profundo de mi alma que no importa qué retos puedan separarnos, ","quoteHighlight":"siempre encontraremos el camino de regreso el uno al otro.","quoteAuthor":"Leo Collins","quoteWork":"The Vow (2012)","thoughtsTitle":"Cosas que me hacen pensar en ti","thoughtsIntro":"Hace un tiempo ya escribí 100 cosas que me hacían pensar en ti y creo que es momento de recrearlo para ti nuevamente, ¿no crees?","thoughts":["las flores delicadas de tonos blancos y pastel","el cielo cuando cae el atardecer","la luz del sol entrando por la ventana en la tarde","ver a Mía durmiendo acurrucada al sol","las mañanas con neblina","el sonido y el olor de la lluvia de fondo (no soy demasiado #fan de la lluvia, pero sigue siendo bonito)","mirar las estrellas en una noche completamente despejada","la brisa suave del mar","las hojas de los árboles cayendo en otoño","ver una mariposa","los arcoíris inesperados que encuentras pasando en zonas de agua","las plantas pequeñas y los brotes nuevos","el brillo de la luna llena por la noche","las gotas de rocío sobre el pasto temprano","el olor a café recién hecho por la mañana","cualquier postre dulce en una pastelería (si tuviera que decir uno, diría los cinnamon rolls)","una taza de té (mi favorito es el de manzana y canela, así que sin duda sería ese)","salir a dar un paseo en las tardes","el olor a pan recién horneado","ir a una cafetería nueva","probar el mismo sabor de helado que me encanta desde que tengo uso de memoria","las tardes de domingo sin ningún plan en particular","el olor a lluvia mojando la tierra seca","unos bombones en forma de animalitos","preparar algo para comer con tu música favorita de fondo","el olor de una vela aromática recién encendida","escuchar canciones y hacer un mini karaoke","la sensación que te queda cuando me dices que ya hiciste todo, te duchaste y comiste algo rico","acurrucarse bajo una manta","la sensación de recibir un abrazo de alguien que amas","escuchar una risa contagiosa (en especial la tuya)","las luces cálidas y amarillas en la noche","el olor a libro nuevo","entrar a un lugar silencioso y escuchar cada acción","ver fotos antiguas de tu familia","un anillo en particular que tengo con un diseño de delfín","una melodía de piano","la sensación de llegar a casa después de un día largo","ponerte la pijama y poder ir a tu cama","la cama fría en un día de calor","ver una película o serie acompañado","los objetos de decoración minimalistas","comprar tazas con diseños bonitos","encontrar algo que llevabas tiempo buscando","el olor a perfume (de fresia)","mirar por la ventana en un viaje por carretera","las tiendas de papelería llenas de cosas por querer","un atardecer en la playa","los caminos rodeados de naturaleza","sentarse en una banca y apreciar dónde estás, quién eres y lo que estás viviendo","descubrir un rincón o lugar en la ciudad","planear un viaje de fin de semana","pensar en los destinos para recorrer el mundo","un puesto de flores frescas en la calle","los peluches tiernos","los calcetines de colores y con diseños","las libretas de Pascualina","el papel de regalo con un moño","los clips, lápices de colores y marcapáginas","ver a dos personas mayores caminando de la mano","el rostro de los perritos cuando buscan afecto","recibir una buena noticia","las pegatinas / stickers","un pensamiento agradable antes de dormirte","sentir la brisa fresca en la cara","un momento de paz total","sentir mariposas en el estómago","la emoción de experimentar el amor","la primera mañana cálida luego de sentir tantos días de frío","el calor suave del sol en pleno invierno","el aire fresco de la mañana","un día nublado ideal para quedarse en casa","el florecer de los árboles en primavera","los pequeños logros cotidianos","encontrar una moneda en el piso","un detalle simple pero lleno de significado","cualquier lugar o cosa que lleve tus colores favoritos","el sonido del viento entre las hojas","los ciervos y su naricita","terminar un libro que te fascinó","el olor a pintura fresca","las notas adhesivas con mensajes bonitos","las manualidades o cosas hechas con dedicación a mano","los hilos de luz reflejados en la pared cuando pega el sol","encontrar recuerdos viejos en tu teléfono","el aroma a canela, vainilla o lavanda","escuchar el sonido de los pasos sobre las hojas secas","la sensación de saber que hay alguien esperándote en casa","una taza de chocolate caliente con malvaviscos en un día de invierno","encontrar una canción perfecta que describe exactamente lo que sientes","el sonido de las páginas de un libro al pasarlas","las notas de voz largas","un destello de luz brillando en el agua","el momento exacto en que empieza a sonar tu canción favorita en la radio","el reflejo de la luna brillando suavemente sobre el mar","guardar un boleto, un ticket o una entrada como recuerdo de un día especial","el sonido de los grillos en una noche cálida de verano","el corazón latiendo rápido por tanto amor","la sensación de que el tiempo se detiene por un segundo cuando todo está perfecto","absolutamente todo lo que tenga que ver con la palabra amor"],"thoughtsItalic":["no soy demasiado #fan de la lluvia, pero sigue siendo bonito","si tuviera que decir uno, diría los cinnamon rolls","mi favorito es el de manzana y canela, así que sin duda sería ese","en especial la tuya","de fresia"],"moviesTitle":"Movies that made me think of us","movies":[{"title":"The Notebook","url":"https://en.wikipedia.org/wiki/The_Notebook","id":"notebook","page":"The Notebook","posterUrl":"https://images.squarespace-cdn.com/content/v1/5c75dfa97d0c9166551f52b1/c90ca701-0eaa-4da9-a1e0-b404b2564ff6/MV5BNzc3Mzg1OGYtZjc3My00Y2NhLTgyOWUtYjRhMmI4OTkwNDg4XkEyXkFqcGdeQXVyMTU3NDU4MDg2._V1_.jpg","poster":"/__local/posters/notebook.jpg","cover":"/__local/posters/notebook.jpg","author":""},{"title":"About Time","url":"https://en.wikipedia.org/wiki/About_Time_(2013_film)","id":"about-time","page":"About Time (2013 film)","posterUrl":"https://imgs.marry-xoxo.com/uploads/image/file/43254/compressed_b1a6c16c-1bdb-4906-be86-ec2f5898bac1.jpg","poster":"/__local/posters/about-time.jpg","cover":"/__local/posters/about-time.jpg","author":""},{"title":"The Proposal","url":"https://en.wikipedia.org/wiki/The_Proposal_(2009_film)","id":"proposal","page":"The Proposal (2009 film)","posterUrl":"https://kritikanstvo.ru/movies/p/proposal/posters/proposal_90091.jpg","poster":"/__local/posters/proposal.jpg","cover":"/__local/posters/proposal.jpg","author":""},{"title":"10 Things I Hate About You","url":"https://en.wikipedia.org/wiki/10_Things_I_Hate_About_You","id":"10-things","page":"10 Things I Hate About You","posterUrl":"https://www.filmartgallery.com/cdn/shop/files/10-Things-I-Hate-About-You-Vintage-Movie-Poster-Original.jpg?v=1743650431","poster":"/__local/posters/10-things.jpg","cover":"/__local/posters/10-things.jpg","author":""},{"title":"50 First Dates","url":"https://en.wikipedia.org/wiki/50_First_Dates","id":"50-first-dates","page":"50 First Dates","posterUrl":"https://n.sinaimg.cn/translate/20171107/Md90-fynmzuk3958417.jpg","poster":"/__local/posters/50-first-dates.jpg","cover":"/__local/posters/50-first-dates.jpg","author":""},{"title":"The Vow","url":"https://en.wikipedia.org/wiki/The_Vow_(2012_film)","id":"the-vow","page":"The Vow (2012 film)","posterUrl":"https://m.media-amazon.com/images/M/MV5BYzk2OThjNWUtY2JhZC00OWIyLTk2ZTktNDQwNmZkM2IzZWM4XkEyXkFqcGc%40._V1_.jpg","poster":"/__local/posters/the-vow.jpg","cover":"/__local/posters/the-vow.jpg","author":""},{"title":"Eternity","url":"https://en.wikipedia.org/wiki/Eternity_(2025_film)","id":"eternity","page":"Eternity (2025 film)","posterUrl":"https://cdn.majorcineplex.com/uploads/content/images/20251208141303_MV5BNzlmZTNiOTAtNzhlOC00ZTA1LWJhNTgtMDQ4YmY4NWIyNTA4XkEyXkFqcGc%40._V1_.jpg","poster":"/__local/posters/eternity.jpg","cover":"/__local/posters/eternity.jpg","author":""},{"title":"Pride and Prejudice","url":"https://en.wikipedia.org/wiki/Pride_%26_Prejudice_(2005_film)","id":"pride-prejudice","page":"Pride & Prejudice (2005 film)","posterUrl":"https://imagens.publicocdn.com/imagens.aspx/198261?tp=KM","poster":"/__local/posters/pride-prejudice.jpg","cover":"/__local/posters/pride-prejudice.jpg","author":""},{"title":"I Married a Witch","url":"https://en.wikipedia.org/wiki/I_Married_a_Witch","id":"married-witch","page":"I Married a Witch","posterUrl":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/I_Married_a_Witch_%281942_film_poster%29.png/500px-I_Married_a_Witch_%281942_film_poster%29.png","poster":"/__local/posters/married-witch.jpg","cover":"/__local/posters/married-witch.jpg","author":""},{"title":"Dracula: A Love Tale","url":"https://en.wikipedia.org/wiki/Dracula_(2025_French_film)","id":"dracula","page":"Dracula (2025 French film)","posterUrl":"https://image.pmgstatic.com/cache/resized/w663/files/images/film/posters/170/348/170348845_th89nr.jpg","poster":"/__local/posters/dracula.jpg","cover":"/__local/posters/dracula.jpg","author":""},{"title":"Frankenstein","url":"https://en.wikipedia.org/wiki/Frankenstein_(2025_film)","id":"frankenstein","page":"Frankenstein (2025 film)","posterUrl":"https://images.squarespace-cdn.com/content/v1/670d2df8bf4f7719f5f20d98/1756198889680-XZ192GG9U6GSARBX32TN/frankenstein_ver2_xlg.jpg?format=1000w","poster":"/__local/posters/frankenstein.jpg","cover":"/__local/posters/frankenstein.jpg","author":""},{"title":"Before Sunrise","url":"https://en.wikipedia.org/wiki/Before_Sunrise","id":"before-sunrise","page":"Before Sunrise","posterUrl":"/movie-posters/before-trilogy.jpg","poster":"/movie-posters/before-trilogy.jpg","cover":"/movie-posters/before-trilogy.jpg","author":""}],"wordsTitle":"Words & concepts about you","words":[{"word":"love","pos":"noun · English","url":"https://en.wikipedia.org/wiki/Love","def":"El amor es un sentimiento profundo y universal de afecto, apego y conexión hacia otra persona, ser o ideal."},{"word":"femininity","pos":"noun · English","url":"https://en.wikipedia.org/wiki/Femininity","def":"El conjunto de cualidades, gestos y maneras de habitar el mundo que una cultura asocia con las mujeres; cambia y florece con cada época."},{"word":"antidote","pos":"noun · English","url":"https://en.wikipedia.org/wiki/Antidote","def":"Un remedio contra el veneno; también aquello que alivia, devuelve la calma y hace bien."},{"word":"petrichor","pos":"noun · Greek roots","url":"https://en.wikipedia.org/wiki/Petrichor","def":"Ese aroma a tierra mojada que la lluvia despierta después de un día seco."},{"word":"ethereal","pos":"adjective · English","url":"https://en.wikipedia.org/wiki/Ethereal","def":"Tan delicado y luminoso que parece pertenecer un poquito al cielo."},{"word":"serendipity","pos":"noun · English","url":"https://en.wikipedia.org/wiki/Serendipity","def":"La alegría de encontrar, sin buscarlo, algo precioso. Como encontrarte a ti."},{"word":"mellifluous","pos":"adjective · Latin roots","url":"https://en.wikipedia.org/wiki/Mellifluous","def":"Una voz o melodía tan suave que parece miel deslizándose por el aire."},{"word":"aurora","pos":"noun · Latin","url":"https://en.wikipedia.org/wiki/Aurora","def":"La primera luz que tiñe el cielo: una promesa tranquila de que algo nuevo comienza."},{"word":"sonder","pos":"noun · coined in English","url":"https://en.wikipedia.org/wiki/Sonder_(word)","def":"Comprender que cada desconocido lleva dentro una vida tan inmensa y real como la nuestra."},{"word":"blossom","pos":"noun · English","url":"https://en.wikipedia.org/wiki/Blossom","def":"La flor que aparece cuando algo, después de esperar, se atreve a abrirse."},{"word":"lullaby","pos":"noun · English","url":"https://en.wikipedia.org/wiki/Lullaby","def":"Una canción bajita que arrulla el corazón hasta que encuentra descanso."}],"erasTitle":"If we lived in another era","erasIntro":"Si viviéramos en otra época:","eras":["En la Francia del siglo XIX, sería un poeta que escribió cien poemas a escondidas solo para verte sonreír.","En el Renacimiento, en Florencia, sería un pintor que convence a su mecenas de que tú debías ser la musa de su obra maestra.","En el antiguo Egipto, sería un astrónomo que le puso tu nombre a la estrella más brillante del cielo.","En el París de los años veinte, sería un pianista de bar que solo toca las canciones que te hacen bailar.","En la antigua Grecia, sería un filósofo que juraba que la verdadera definición de belleza eras tú.","En el Londres de los años sesenta, sería un fotógrafo que no dejaba de retratarte en cada calle de la ciudad."],"booksToReadTitle":"Texts of her","booksToRead":[{"title":"Pride and Prejudice","author":"Jane Austen","url":"https://en.wikipedia.org/wiki/Pride_and_Prejudice","cover":"/__local/texts/pride-prejudice.jpg","imagePage":"Pride and Prejudice"},{"title":"Brief einer Unbekannten","author":"Stefan Zweig","url":"https://en.wikipedia.org/wiki/Letter_from_an_Unknown_Woman","cover":"/__local/texts/unknown-woman.jpg","imagePage":"Letter from an Unknown Woman"},{"title":"Le Petit Prince","author":"Antoine de Saint-Exupéry","url":"https://en.wikipedia.org/wiki/The_Little_Prince","cover":"/__local/texts/little-prince.jpg","imagePage":"The Little Prince"},{"title":"Veinte poemas de amor y una canción desesperada","author":"Pablo Neruda","url":"https://es.wikipedia.org/wiki/Veinte_poemas_de_amor_y_una_canci%C3%B3n_desesperada","cover":"/__local/texts/neruda-poems.jpg","imagePage":"Twenty Love Poems and a Song of Despair"},{"title":"Briefe an einen jungen Dichter","author":"Rainer Maria Rilke","url":"https://en.wikipedia.org/wiki/Letters_to_a_Young_Poet","cover":"/__local/texts/young-poet.png","imagePage":"Letters to a Young Poet"},{"title":"Love Letters: Vita & Virginia","author":"Vita Sackville-West & Virginia Woolf","url":"https://en.wikipedia.org/wiki/Vita_Sackville-West","cover":"/__local/texts/virginia-woolf.jpg","imagePage":"Virginia Woolf"},{"title":"Normal People","author":"Sally Rooney","url":"https://en.wikipedia.org/wiki/Normal_People","cover":"/__local/texts/normal-people.png","imagePage":"Normal People"},{"title":"Nesnesitelná lehkost bytí","author":"Milan Kundera","url":"https://en.wikipedia.org/wiki/The_Unbearable_Lightness_of_Being","cover":"/__local/texts/lightness-of-being.jpg","imagePage":"The Unbearable Lightness of Being"},{"title":"Die Kunst des Liebens","author":"Erich Fromm","url":"https://en.wikipedia.org/wiki/The_Art_of_Loving","cover":"/__local/texts/art-of-loving.jpg","imagePage":"The Art of Loving"}],"philosophyTitle":"Her Philosophy","philosophy":["Haces que la vida cotidiana sea más bonita con tu presencia en cualquier lugar.","Llenas mis días de alegría, amor y tranquilidad.","Creas belleza en los detalles más pequeños y simples de la vida.","Inspiras a todos a expresarse con completa libertad y sinceridad con tu forma de ser.","Transformas cualquier momento ordinario en algo completamente especial a tu lado."],"quotesTitle":"Thoughts on you","quotes":[{"text":"Te miré y supe que en ti había algo que nunca antes había encontrado en nadie más.","source":"Julio Cortázar"},{"text":"Si sé lo que es el amor, es gracias a ti.","source":"Hermann Hesse"},{"text":"Ella no necesita que nadie la complete, solo necesita a alguien que la acepte por completo.","source":"Atticus"},{"text":"Andábamos sin buscarnos, pero sabiendo que andábamos para encontrarnos.","source":"Julio Cortázar"},{"text":"En todo el mundo no hay un corazón para mí como el tuyo. En todo el mundo no hay amor para ti como el mío.","source":"Maya Angelou"},{"text":"Me enamoré de ella cuando estábamos juntos, y luego me enamoré más de ella en los años que estuvimos separados.","source":"The Notebook"}],"artistsTitle":"Artists who talk her","artists":[{"id":"guillermo-del-toro","name":"Guillermo del Toro","description":"Cineasta mexicano de mundos fantásticos y criaturas inolvidables.","url":"https://en.wikipedia.org/wiki/Guillermo_del_Toro","portrait":"/__local/artists/guillermo-del-toro.jpg","imageSource":"https://en.wikipedia.org/wiki/Guillermo_del_Toro"},{"id":"cindy-sherman","name":"Cindy Sherman","description":"Artista y fotógrafa que explora la identidad a través del autorretrato.","url":"https://en.wikipedia.org/wiki/Cindy_Sherman","portrait":"/__local/artists/cindy-sherman.jpg","imageSource":"https://en.wikipedia.org/wiki/Cindy_Sherman"},{"id":"vivian-maier","name":"Vivian Maier","description":"Fotógrafa callejera de las pequeñas historias de la vida cotidiana.","url":"https://en.wikipedia.org/wiki/Vivian_Maier","portrait":"/__local/artists/vivian-maier.jpg","imageSource":"https://en.wikipedia.org/wiki/Vivian_Maier"},{"id":"gustav-klimt","name":"Gustav Klimt","description":"Pintor austriaco de simbolismo, delicadeza y mundos dorados.","url":"https://en.wikipedia.org/wiki/Gustav_Klimt","portrait":"/__local/artists/gustav-klimt.jpg","imageSource":"https://en.wikipedia.org/wiki/Gustav_Klimt"},{"id":"frank-ocean","name":"Frank Ocean","description":"Cantante y compositor de canciones íntimas y R&B alternativo.","url":"https://en.wikipedia.org/wiki/Frank_Ocean","portrait":"/__local/artists/frank-ocean.jpg","imageSource":"https://en.wikipedia.org/wiki/Frank_Ocean"},{"id":"egon-schiele","name":"Egon Schiele","description":"Pintor expresionista austriaco de trazos intensos y emociones abiertas.","url":"https://en.wikipedia.org/wiki/Egon_Schiele","portrait":"/__local/artists/egon-schiele.jpg","imageSource":"https://en.wikipedia.org/wiki/Egon_Schiele"},{"id":"jane-austen","name":"Jane Austen","description":"Novelista inglesa de amor, ironía y retratos de la vida social.","url":"https://en.wikipedia.org/wiki/Jane_Austen","portrait":"/__local/artists/jane-austen.jpg","imageSource":"https://en.wikipedia.org/wiki/Jane_Austen"},{"id":"mario-benedetti","name":"Mario Benedetti","description":"Poeta y escritor uruguayo del amor y lo cotidiano.","url":"https://en.wikipedia.org/wiki/Mario_Benedetti","portrait":"/__local/artists/mario-benedetti.jpg","imageSource":"https://en.wikipedia.org/wiki/Mario_Benedetti"},{"id":"oscar-wilde","name":"Oscar Wilde","description":"Escritor, poeta y dramaturgo irlandés de ingenio y sensibilidad.","url":"https://en.wikipedia.org/wiki/Oscar_Wilde","portrait":"/__local/artists/oscar-wilde.jpg","imageSource":"https://en.wikipedia.org/wiki/Oscar_Wilde"},{"id":"hayao-miyazaki","name":"Hayao Miyazaki","description":"Director de animación japonés y cofundador de Studio Ghibli.","url":"https://en.wikipedia.org/wiki/Hayao_Miyazaki","portrait":"/__local/artists/hayao-miyazaki.jpg","imageSource":"https://en.wikipedia.org/wiki/Hayao_Miyazaki"}],"artTitle":"Art for her","artworks":[{"id":"klimt-kiss","title":"The Kiss","artist":"Gustav Klimt","url":"https://en.wikipedia.org/wiki/The_Kiss_(Klimt)","photo":"/art/gallery/gustav-klimt-the-kiss.jpg"},{"id":"monet-water-lilies","title":"Water Lilies","artist":"Claude Monet","url":"https://en.wikipedia.org/wiki/Water_Lilies_(Monet_series)","photo":"/art/gallery/claude-monet-water-lilies.jpg"},{"id":"birth-of-venus","title":"The Birth of Venus","artist":"Sandro Botticelli","url":"https://en.wikipedia.org/wiki/The_Birth_of_Venus","photo":"/art/renaissance/sandro-botticelli-the-birth-of-venus.jpg"},{"id":"wanderer","title":"Wanderer Above the Sea of Fog","artist":"Caspar David Friedrich","url":"https://en.wikipedia.org/wiki/Wanderer_Above_the_Sea_of_Fog","photo":"/art/gallery/caspar-david-friedrich-the-wanderer-above-the-sea-of-fog.jpg"},{"id":"magritte-lovers","title":"The Lovers","artist":"René Magritte","url":"https://en.wikipedia.org/wiki/The_Lovers_(Magritte)","photo":"/art/gallery/rene-magritte-the-lovers.jpg"},{"id":"hayez-kiss","title":"The Kiss","artist":"Francesco Hayez","url":"https://en.wikipedia.org/wiki/The_Kiss_(Hayez)","photo":"/__local/artworks/hayez-kiss.jpg"},{"id":"chagall-over-town","title":"Over the Town","artist":"Marc Chagall","url":"https://fr.wikipedia.org/wiki/Au-dessus_de_la_ville","photo":"/__local/artworks/chagall-over-town.jpg"},{"id":"monet-stroll","title":"The Stroll","artist":"Claude Monet","url":"https://en.wikipedia.org/wiki/Woman_with_a_Parasol_–_Madame_Monet_and_Her_Son","photo":"/art/gallery/claude-monet-woman-with-a-parasol-madame-monet-and-her-son.jpg"},{"id":"schiele-embrace","title":"The Embrace","artist":"Egon Schiele","url":"https://es.wikipedia.org/wiki/El_abrazo_(pareja_de_enamorados_II)","photo":"/__local/artworks/schiele-embrace.jpg"},{"id":"vermeer-pearl","title":"Girl with a Pearl Earring","artist":"Johannes Vermeer","url":"https://en.wikipedia.org/wiki/Girl_with_a_Pearl_Earring","photo":"/art/gallery/johannes-vermeer-girl-with-a-pearl-earring.jpg"},{"id":"chagall-birthday","title":"Birthday","artist":"Marc Chagall","url":"https://en.wikipedia.org/wiki/List_of_artworks_by_Marc_Chagall#1914%E2%80%931922,_Russia","photo":"/__local/artworks/chagall-birthday.png"}],"disneyTitle":"Eres","disneyText":["Eres lo más preciado que mi corazón conoce. Sin ti, me faltaría el aire; contigo, todo vuelve a tener sentido. Llegaste a mi vida como un pequeño caos hermoso, y desde entonces mis venas, mi alma y mis días aprendieron a pronunciar tu nombre. No quiero algo pasajero: quiero caminar contigo y que la vida nos encuentre quedándonos.","Soy completamente tuya y quiero cuidar tu corazón hasta el final de mis días. Te amo; no conozco un amor más grande que el que siento ahora mismo por ti.","Eres más de lo que alguna vez imaginé, más de lo que creí merecer y más maravillosa de lo que cualquier palabra alcanza a decir."],"songsTitle":"Songs for her","songs":[{"title":"About You","artist":"The 1975","url":"https://www.youtube.com/watch?v=tGv7CUutzqU"},{"title":"Never Be the Same","artist":"Camila Cabello","url":"https://www.youtube.com/watch?v=Ph54wQG8ynk"},{"title":"Cinderella","artist":"Mac Miller feat. Ty Dolla $ign","url":"https://www.youtube.com/watch?v=FFamEq1PilQ"},{"title":"Sweet Dreams, TN","artist":"The Last Shadow Puppets","url":"https://www.youtube.com/watch?v=qBeBqcqdSrk"},{"title":"Nothing’s Gonna Hurt You Baby","artist":"Cigarettes After Sex","url":"https://www.youtube.com/watch?v=QI8VrXkffcg"},{"title":"honeybee","artist":"Olivia Rodrigo","url":"https://www.youtube.com/watch?v=60rlboK94mE"},{"title":"intro (end of the world)","artist":"Ariana Grande","url":"https://www.youtube.com/watch?v=p7jATa6Soag"},{"title":"Love I You","artist":"ROLE MODEL","url":"https://www.youtube.com/watch?v=bV_eXI9i9Ms"}],"placesTitle":"Places that makes me think about you :)","places":[{"id":"galesnjak","name":"Galešnjak, the Heart-shaped Island","area":"Croatia","lat":43.97812222,"lng":15.38365,"distance":1700,"photo":"/__local/places/galesnjak.jpg","source":"https://en.wikipedia.org/wiki/Galešnjak","url":"https://earth.google.com/web/@43.97812222,15.38365,0a,1700d,35y,0h,0t,0r"},{"id":"fairy-bridge","name":"Fairy Bridge (Xianren)","area":"Guangxi, China","lat":24.687723,"lng":106.799984,"distance":1600,"photo":"/__local/places/fairy-bridge.jpg","source":"https://www.naturalarches.org/big_arches/big-FairyBridge.htm","url":"https://earth.google.com/web/@24.687723,106.799984,0a,1600d,35y,0h,0t,0r"},{"id":"el-ojo","name":"The Eye, the Rotating Island","area":"Argentina","lat":-34.25222222,"lng":-58.83,"distance":500,"photo":"/__local/places/el-ojo.jpg","source":"https://en.wikipedia.org/wiki/El_Ojo","url":"https://earth.google.com/web/@-34.25222222,-58.83,0a,500d,35y,0h,0t,0r"},{"id":"irati","name":"Irati Forest","area":"Spain","lat":43,"lng":-1.0833,"distance":10000,"photo":"/__local/places/irati.jpg","source":"https://en.wikipedia.org/wiki/Irati_Forest","url":"https://earth.google.com/web/@43,-1.0833,0a,10000d,35y,0h,0t,0r"},{"id":"fly-geyser","name":"Fly Geyser","area":"Nevada, United States","lat":40.85944444,"lng":-119.33194444,"distance":1200,"photo":"/__local/places/fly-geyser.jpg","source":"https://en.wikipedia.org/wiki/Fly_Geyser","url":"https://earth.google.com/web/@40.85944444,-119.33194444,0a,1200d,35y,0h,0t,0r"},{"id":"zhangye","name":"Zhangye Danxia Geopark","area":"China","lat":38.91555,"lng":100.1332,"distance":7000,"photo":"/__local/places/zhangye.jpg","source":"https://en.wikipedia.org/wiki/Zhangye_National_Geopark","url":"https://earth.google.com/web/@38.91555,100.1332,0a,7000d,35y,0h,0t,0r"},{"id":"aurora","name":"Northern Lights over Kirkjufell","area":"Iceland","lat":64.9410355,"lng":-23.3056896,"distance":6000,"photo":"/__local/places/aurora.jpg","source":"https://commons.wikimedia.org/wiki/File:Kirkjufell,_Snæfellsnes,_Iceland.jpeg","credit":"Andrés Nieto Porras · CC BY-SA 2.0","note":"Google Earth muestra el paisaje; las auroras están en la fotografía, no en directo.","url":"https://earth.google.com/web/@64.9410355,-23.3056896,0a,6000d,35y,0h,0t,0r"},{"id":"macdonnell","name":"Lake MacDonnell","area":"Australia","lat":-32.042841,"lng":133.00122,"distance":6500,"photo":"/__local/places/macdonnell.jpg","source":"https://www.cedunatourism.com.au/","credit":"Ceduna Tourism","url":"https://earth.google.com/web/@-32.042841,133.00122,0a,6500d,35y,0h,0t,0r"},{"id":"pamukkale","name":"Pamukkale","area":"Türkiye","lat":37.92388889,"lng":29.12333333,"distance":2000,"photo":"/__local/places/pamukkale.jpg","source":"https://en.wikipedia.org/wiki/Pamukkale","url":"https://earth.google.com/web/@37.92388889,29.12333333,0a,2000d,35y,0h,0t,0r"}],"shuffledThoughts":["la primera mañana cálida luego de sentir tantos días de frío","las notas adhesivas con mensajes bonitos","la brisa suave del mar","un pensamiento agradable antes de dormirte","el sonido de las páginas de un libro al pasarlas","el reflejo de la luna brillando suavemente sobre el mar","los calcetines de colores y con diseños","probar el mismo sabor de helado que me encanta desde que tengo uso de memoria","guardar un boleto, un ticket o una entrada como recuerdo de un día especial","las plantas pequeñas y los brotes nuevos","un atardecer en la playa","entrar a un lugar silencioso y escuchar cada acción","el aroma a canela, vainilla o lavanda","el olor a pintura fresca","mirar las estrellas en una noche completamente despejada","planear un viaje de fin de semana","preparar algo para comer con tu música favorita de fondo","el brillo de la luna llena por la noche","comprar tazas con diseños bonitos","cualquier postre dulce en una pastelería (si tuviera que decir uno, diría los cinnamon rolls)","las manualidades o cosas hechas con dedicación a mano","encontrar una canción perfecta que describe exactamente lo que sientes","acurrucarse bajo una manta","descubrir un rincón o lugar en la ciudad","una taza de té (mi favorito es el de manzana y canela, así que sin duda sería ese)","mirar por la ventana en un viaje por carretera","la emoción de experimentar el amor","el sonido del viento entre las hojas","el florecer de los árboles en primavera","el olor de una vela aromática recién encendida","ponerte la pijama y poder ir a tu cama","la sensación de llegar a casa después de un día largo","la sensación de que el tiempo se detiene por un segundo cuando todo está perfecto","la luz del sol entrando por la ventana en la tarde","el olor a libro nuevo","los arcoíris inesperados que encuentras pasando en zonas de agua","ir a una cafetería nueva","las tiendas de papelería llenas de cosas por querer","cualquier lugar o cosa que lleve tus colores favoritos","los objetos de decoración minimalistas","la sensación de recibir un abrazo de alguien que amas","el rostro de los perritos cuando buscan afecto","los pequeños logros cotidianos","ver a dos personas mayores caminando de la mano","sentir la brisa fresca en la cara","los peluches tiernos","ver a Mía durmiendo acurrucada al sol","escuchar el sonido de los pasos sobre las hojas secas","un anillo en particular que tengo con un diseño de delfín","encontrar recuerdos viejos en tu teléfono","ver una mariposa","la cama fría en un día de calor","el momento exacto en que empieza a sonar tu canción favorita en la radio","el olor a lluvia mojando la tierra seca","una melodía de piano","un puesto de flores frescas en la calle","un día nublado ideal para quedarse en casa","escuchar canciones y hacer un mini karaoke","el sonido de los grillos en una noche cálida de verano","ver fotos antiguas de tu familia","sentarse en una banca y apreciar dónde estás, quién eres y lo que estás viviendo","las hojas de los árboles cayendo en otoño","la sensación de saber que hay alguien esperándote en casa","el corazón latiendo rápido por tanto amor","las notas de voz largas","las luces cálidas y amarillas en la noche","el calor suave del sol en pleno invierno","escuchar una risa contagiosa (en especial la tuya)","las flores delicadas de tonos blancos y pastel","las tardes de domingo sin ningún plan en particular","pensar en los destinos para recorrer el mundo","un detalle simple pero lleno de significado","sentir mariposas en el estómago","la sensación que te queda cuando me dices que ya hiciste todo, te duchaste y comiste algo rico","el papel de regalo con un moño","el olor a perfume (de fresia)","las mañanas con neblina","los clips, lápices de colores y marcapáginas","el sonido y el olor de la lluvia de fondo (no soy demasiado #fan de la lluvia, pero sigue siendo bonito)","recibir una buena noticia","una taza de chocolate caliente con malvaviscos en un día de invierno","las pegatinas / stickers","el aire fresco de la mañana","encontrar algo que llevabas tiempo buscando","el olor a pan recién horneado","salir a dar un paseo en las tardes","las gotas de rocío sobre el pasto temprano","encontrar una moneda en el piso","el cielo cuando cae el atardecer","los caminos rodeados de naturaleza","ver una película o serie acompañado","los ciervos y su naricita","un destello de luz brillando en el agua","las libretas de Pascualina","el olor a café recién hecho por la mañana","los hilos de luz reflejados en la pared cuando pega el sol","unos bombones en forma de animalitos","terminar un libro que te fascinó","un momento de paz total","absolutamente todo lo que tenga que ver con la palabra amor"]};const nirvanaEnd={"title":"End","paragraphs":["Mi querido Ángel,","Espero de todo corazón que hayas disfrutado de este pequeño espacio que creé para ti. Sé que se queda pequeño frente a todo lo que mereces, pero espero que estas pequeñas cosas te hayan hecho feliz. Cada detalle está hecho con todo el amor del mundo, pensando en ti y en las cosas que podrían gustarte.","Espero que lo atesores y que tengas un cumpleaños maravilloso, porque eso es lo que te mereces. Sabes que te amo con todo mi corazón y que siempre voy a estar aquí para ti: en cada momento, en cada paso que des, quiero seguir caminando a tu lado.","Sigue siendo tú. Gracias por todo el amor que me brindas a diario, por ser una persona tan maravillosa, tan auténtica y tan dulce; por tratar con amabilidad incluso a quienes a veces no saben corresponderla. Eres más de lo que cualquiera podría desear y, de verdad, te mereces el mundo entero.","Permíteme, de todo corazón, pasar mi vida entera junto a ti. No puedo imaginar una alegría más grande que compartirla contigo. Eres el motivo por el que despierto cada día tan feliz y lleno de esperanza. Te amo como no tienes idea.","Feliz cumpleaños, amor de mi vida.","Con amor,\nJules."]};
